package com.turing.app.api.interview.controller;
import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.jayway.jsonpath.JsonPath;import com.turing.app.api.auth.service.AuthMailService;import com.turing.app.api.user.repository.UserRepository;import jakarta.servlet.http.Cookie;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;
@SpringBootTest@AutoConfigureMockMvc@Testcontainers@ActiveProfiles("test")@Import(InterviewControllerIT.MailConfig.class)class InterviewControllerIT{@Container@ServiceConnection static PostgreSQLContainer<?>postgres=new PostgreSQLContainer<>("postgres:17-alpine");@Autowired org.springframework.test.web.servlet.MockMvc mvc;@Autowired Mail mail;@Autowired UserRepository users;@Autowired JdbcTemplate jdbc;
 @Test void protectsStudentViewAndManagesScheduleStatusFeedbackAndVersions()throws Exception{Cookie admin=admin("interview-admin@example.com"),student=session("interview-student@example.com"),other=session("interview-other@example.com");UUID studentId=users.findByEmailIgnoreCase("interview-student@example.com").orElseThrow().getId(),application=seed(studentId);String body="{\"startsAt\":\"2026-09-03T10:00:00Z\",\"endsAt\":\"2026-09-03T11:00:00Z\",\"locationType\":\"ONLINE\",\"meetingUrl\":\"https://meet.example/interview\"}";String id=JsonPath.read(mvc.perform(post("/api/admin/applications/"+application+"/interviews").with(csrf()).cookie(admin).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("SCHEDULED")).andReturn().getResponse().getContentAsString(),"$.id");mvc.perform(get("/api/me/interviews").cookie(student)).andExpect(status().isOk()).andExpect(jsonPath("$[0].meetingUrl").value("https://meet.example/interview")).andExpect(jsonPath("$[0].feedback").doesNotExist());mvc.perform(get("/api/me/interviews/"+id).cookie(other)).andExpect(status().isNotFound());mvc.perform(patch("/api/admin/interviews/"+id+"/status").with(csrf()).cookie(admin).contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"COMPLETED\",\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.version").value(1));mvc.perform(patch("/api/admin/interviews/"+id+"/status").with(csrf()).cookie(admin).contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"CANCELLED\",\"version\":0}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("INTERVIEW_VERSION_CONFLICT"));mvc.perform(put("/api/admin/interviews/"+id+"/feedback").with(csrf()).cookie(admin).contentType(MediaType.APPLICATION_JSON).content("{\"score\":85,\"notes\":\"Güçlü iletişim\",\"recommendation\":\"Olumlu\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.feedback[0].notes").value("Güçlü iletişim"));mvc.perform(get("/api/me/interviews/"+id).cookie(student)).andExpect(status().isOk()).andExpect(jsonPath("$.feedback").doesNotExist()).andExpect(jsonPath("$.recommendation").doesNotExist());assertThat(jdbc.queryForObject("select count(*) from audit_logs where entity_id=?",Integer.class,UUID.fromString(id))).isEqualTo(3);}
 private UUID seed(UUID student){OffsetDateTime now=OffsetDateTime.now(ZoneOffset.UTC);UUID profile=UUID.randomUUID(),program=UUID.randomUUID(),period=UUID.randomUUID(),form=UUID.randomUUID(),application=UUID.randomUUID();jdbc.update("insert into student_profiles(id,user_id,created_at,updated_at,version)values(?,?,?,?,0)",profile,student,now,now);jdbc.update("insert into scholarship_programs(id,name,slug,description,active,created_at,updated_at,version)values(?,?,?,?,true,?,?,0)",program,"Interview Program","interview-"+program,"Test",now,now);jdbc.update("insert into application_periods(id,program_id,name,academic_year,starts_at,ends_at,status,allow_withdrawal,created_at,updated_at,version)values(?,?,?,?,?,?,'EVALUATION',true,?,?,0)",period,program,"Interview Period","2026-2027",now.minusDays(2),now.plusDays(2),now,now);jdbc.update("insert into forms(id,period_id,name,version_number,status,published_at,created_at,updated_at,version)values(?,?,?,1,'PUBLISHED',?,?,?,0)",form,period,"Form",now,now,now);jdbc.update("insert into applications(id,profile_id,period_id,form_id,status,completion,submitted_at,created_at,updated_at,version)values(?,?,?,?,'SHORTLISTED',100,?,?,?,0)",application,profile,period,form,now,now,now);return application;}
 private Cookie admin(String email)throws Exception{session(email);UUID id=users.findByEmailIgnoreCase(email).orElseThrow().getId();jdbc.update("update users set role='ADMIN' where id=?",id);return login(email);}private Cookie session(String email)throws Exception{mvc.perform(post("/api/auth/register").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"strong-pass-123\",\"firstName\":\"Test\",\"lastName\":\"User\"}")).andExpect(status().isCreated());mvc.perform(post("/api/auth/verify-email").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"token\":\""+mail.tokens.get(email)+"\"}")).andExpect(status().isOk());return login(email);}private Cookie login(String email)throws Exception{return mvc.perform(post("/api/auth/login").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"strong-pass-123\"}")).andReturn().getResponse().getCookie("TURING_ACCESS_TOKEN");}@TestConfiguration static class MailConfig{@Bean@Primary Mail mail(){return new Mail();}}static class Mail implements AuthMailService{final Map<String,String>tokens=new ConcurrentHashMap<>();public void sendVerification(String email,String token){tokens.put(email,token);}public void sendPasswordReset(String email,String token){}}}
